SOURCES = {'invsqrt/__init__.py': '"""Generator for the invsqrt benchmark circuit (|x>|0> -> exp(2 pi i / sqrt(x)) |x>|0>).\n\nLineage and licence\n-------------------\nThis package started as a port of the public, Apache-2.0 notebook\n"VQCC invsqrt 13.94x - full source" by marsyas (Houssem Alayet),\nhttps://www.kaggle.com/code/marsyas/vqcc-invsqrt-13-94x-full-source\n(read 2026-10-28; ipynb SHA-256 4da93524...). That notebook credits, as ideas it\nre-implemented: Sumit Chongder and kozykappa (signed-digit rows), anazemcev (H/L split,\nexact compilation), Dmitrii Gluzdov (merged unlookup), Artem (exact-domain pass),\nauqib92 (nested windows), mizeroluckygall and lightningv08 (angle calibration),\nrudrabhaskar (direct polynomial phasing).\n\nThe port was re-typed from the notebook text (never executed). Changes from the\noriginal are marked "change:" in the module docstrings. Copyright of the original\ncode remains with its author; it is used under the Apache License, Version 2.0\n(http://www.apache.org/licenses/LICENSE-2.0).\n\nModules\n-------\nmodel     exact integer model of the arithmetic and phase (all legal x)\nfit       per-segment coefficient tables (LP + integer neighbourhood search)\ncalib     LP calibration of the rotation angles against the exact model\nbuild     the kickmix circuit builder (normalization, lookup, Horner rows, phasing)\nexact     exact-domain post-pass over all legal inputs\ncheck     kickmix simulation of a built circuit against the model\ngenerate  end-to-end pipeline driven by a JSON config\n"""\n', 'invsqrt/build.py': '"""kickmix builder for the invsqrt circuit (the arithmetic is the one in model.py).\n\nStages: thermometer of leading zeros -> 5 CSWAP normalization stages -> 8-bit lookup of\n(u, H, C1, C2) -> phase H (and the constant 1/2 bit) and erase H by measurement ->\nstep A (T = C1 - rows of C2) -> step B (L += rows of T, nested windows) -> phase L ->\nuncompute B, A -> one merged measurement-based unlookup -> un-normalize with flags\ncleared by HMR and conditioned multi-controlled Z.\n\nPorted from marsyas\'s Apache-2.0 notebook (build.py and hsplit.py there; see the package\ndocstring). change: only the signed-digit + H/L-split + nested-window + measured\nunlookup path of the 13.94x build is kept; Booth rows, plain rows, product temps and the\nunfused shift register are dropped. The adder and stages are unchanged.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom fractions import Fraction\n\nimport numpy as np\nimport kickmix as km\n\nfrom . import fit as Fm\nfrom . import model as M\n\n\n@dataclass\nclass Opts:\n    WA: int | None = None      # step A window top\n    gA: int = 1                # step A guard qubits (1: offset scheme)\n    mdel: bool = True          # merged measurement-based unlookup\n    wins: list | None = None   # nested step-B windows [(K, rows)], outer -> inner\n    wcb: list | None = None    # window counter bits\n    kbig: int = 0              # in-place prefix positions for the big (non-window) rows\n    qcap: int | None = None    # qubit cap for in-place adder prefixes in step B\n    cap: int | None = None\n\n\nclass B:\n    def __init__(self):\n        self.b = km.CircuitBuilder()\n        self.peak = (0, \'\')\n        self.label = \'\'\n        self.cap = None\n        self.phasefix = True\n\n    def note(self, where=\'\'):\n        n = self.b.num_allocated_qubits\n        if n > self.peak[0]:\n            self.peak = (n, self.label + where)\n\n    # ---------------- adder -----------------\n    def add_ip(self, srcs, tgt, cin, k):\n        """tgt += srcs + cin with a k-position Cuccaro (in-place MAJ) prefix: saves k carry\n        ancillas (k-1 if cin is None) for +k Toffolis. srcs[0..k-1] must be plain qubits."""\n        b = self.b\n        n = len(tgt)\n        srcs = list(srcs) + [None] * (n - len(srcs))\n        assert all(isinstance(s_, km.q) for s_ in srcs[:k]) and k < n - 1\n        own = cin is None\n        c0 = b.alloc_qubits(1)[0] if own else cin\n        cs = [c0] + list(srcs[:k])\n        for i in range(k):\n            c, bb, a = cs[i], tgt[i], srcs[i]\n            b.cx(a, bb); b.cx(a, c); b.ccx(c, bb, a)\n        self.add(srcs[k:], list(tgt[k:]), cin=srcs[k - 1])\n        for i in reversed(range(k)):\n            c, bb, a = cs[i], tgt[i], srcs[i]\n            b.ccx(c, bb, a); b.cx(a, c); b.cx(c, bb)\n        if own:\n            b.free(km.array([c0]))\n\n    def add(self, srcs, tgt, subtract=False, cin=None, cout=None):\n        """tgt += sum_i src_i 2^i + cin (mod 2^len(tgt)); with cout, the carry out of the top\n        position is XORed into cout. srcs[i] is None (zero) or a qubit; repeats allowed.\n        Gidney-style: carries computed with init_and and erased with del_and."""\n        b = self.b\n        n = len(tgt)\n        srcs = list(srcs) + [None] * (n - len(srcs))\n        assert len(srcs) == n\n        assert all(s_ is None or isinstance(s_, km.q) for s_ in srcs)\n        lo = 0\n        if cin is None:\n            while lo < n and srcs[lo] is None:\n                lo += 1\n        if lo == n:\n            return\n        srcs = srcs[lo:]\n        tgt = list(tgt[lo:])\n        n = len(tgt)\n        if subtract:\n            b.x(km.array(tgt))\n        K = n - 1 if cout is not None else n - 2   # internal carries c_1..c_K\n        K = max(K, 0)\n        carries = b.alloc_qubits(K) if K else []\n\n        def cin_of(i):\n            if i == 0:\n                return cin\n            return carries[i - 1] if i - 1 < K else None\n\n        for i in range(n):\n            a = srcs[i]\n            bb = tgt[i]\n            c = cin_of(i)\n            if i < K:\n                dest, init = carries[i], True\n            elif cout is None and i == n - 2:\n                dest, init = tgt[n - 1], False\n            elif cout is not None and i == n - 1:\n                dest, init = cout, False\n            else:\n                dest = None\n            if dest is None:\n                if a is not None:\n                    b.cx(a, bb)\n                if c is not None and (cout is not None or n == 1):\n                    b.cx(c, bb)\n                self.note(f\' add n={n}\')\n                continue\n            if a is None:\n                if init:\n                    b.init_and(bb, c, dest)\n                else:\n                    b.ccx(bb, c, dest)\n                b.cx(c, bb)\n            else:\n                if c is not None:\n                    b.cx(c, a); b.cx(c, bb)\n                if init:\n                    b.init_and(a, bb, dest)\n                else:\n                    b.ccx(a, bb, dest)\n                if c is not None:\n                    b.cx(c, dest)\n                if c is not None:\n                    b.cx(c, a)\n                b.cx(a, bb)\n            self.note(f\' add n={n}\')\n        for i in reversed(range(K)):\n            bb = tgt[i]\n            c = cin_of(i)\n            a = srcs[i]\n            if a is None:\n                b.cx(c, bb)\n                b.del_and(bb, c, carries[i])\n                b.cx(c, bb)\n            else:\n                if c is not None:\n                    b.cx(c, carries[i])\n                b.cx(a, bb)\n                if c is not None:\n                    b.cx(c, a)\n                b.del_and(a, bb, carries[i])\n                if c is not None:\n                    b.cx(c, a)\n                b.cx(a, bb)\n        if carries:\n            b.free(carries)\n        if subtract:\n            b.x(km.array(tgt))\n\n\ndef sd_step(bb: B, x, rows, op, acc, e_of, W, guard, fwd):\n    """Signed-digit rows: fwd: acc -= sum_i (2b_i-1) rd(op, e_i+1); else the exact inverse."""\n    b = bb.b\n    g1 = len(guard) == 1\n    win = (list(acc[:W + 1]) if g1 else list(acc[:W])) + list(guard)\n    high = list(acc[W + 1:]) if g1 else list(acc[W:])\n    gsrc = [guard[0]] + [guard[1]] * (len(high) - 1) if len(guard) == 2 else None\n\n    def row(i):\n        e = e_of(i) + 1\n        srcs = [op[p + e] if 0 <= p + e < len(op) else None for p in range(len(win))]\n        assert len(op) - e <= len(win), (\'window too small\', len(op) - e, len(win))\n        cin = op[e - 1] if 1 <= e <= len(op) else None\n        if all(q is None for q in srcs) and cin is None:\n            return\n        ctl = x[i]\n        if not fwd:\n            b.x(ctl)\n        for q in win:\n            b.cx(ctl, q)\n        bb.add(srcs, win, cin=cin)\n        for q in win:\n            b.cx(ctl, q)\n        if not fwd:\n            b.x(ctl)\n\n    order = list(rows) if fwd else list(reversed(rows))\n    if g1:\n        top = acc[W]\n        g = guard[0]\n        if fwd:\n            b.x(top); b.cx(top, g)\n            for i in order:\n                row(i)\n            if high:\n                bb.add([top], high)\n                bb.add([g], high, subtract=True)\n            b.x(top)\n        else:\n            b.x(top)\n            if high:\n                bb.add([g], high)\n                bb.add([top], high, subtract=True)\n            for i in order:\n                row(i)\n            b.cx(top, g); b.x(top)\n        return\n    if not fwd and high:\n        bb.add(gsrc, high, subtract=True)\n    for i in order:\n        row(i)\n    if fwd and high:\n        bb.add(gsrc, high, subtract=False)\n\n\ndef fused_phase(bb: B, R, h0, angfn, flags4):\n    """Phase sum_j ang(j) * bit_j(R << s), s = f2 + 2 f4 + 4 f8 + 8 f16 (s <= 10).\n    R: data qubits R[0..h0] followed by 3 clean ext qubits. f2, f4 in place (CSWAP);\n    f8/f16 fused: Z_j = R_j ^ f8 (R_j ^ R_{j-4}) ^ f16 (R_j ^ R_{j-8}) into one temp,\n    Z_POW, then HMR with Clifford fix-up. angfn(j) -> Fraction half-turns or None."""\n    b = bb.b\n    f2, f4, f8, f16 = flags4\n    assert len(R) == h0 + 4\n    hiR = h0 + 3\n    shifts = [(1, f2, h0), (2, f4, h0 + 1)]\n    empty = {(1, h0), (2, h0 + 1), (2, h0)}   # targets above every earlier write are zero\n    for k, f, hi in shifts:\n        for i in range(hi, -1, -1):\n            if (k, i) in empty:\n                b.init_and(f, R[i], R[i + k]); b.cx(R[i + k], R[i])\n            else:\n                b.cswap(f, R[i], R[i + k])\n    z = b.alloc_qubits(1)[0]\n    bb.note(\' fused phase\')\n\n    def term(f, j, k, act):\n        qa = R[j] if j <= hiR else None\n        qb = R[j - k] if 0 <= j - k <= (hiR if k == 4 else h0 + 2) else None\n        if qa is None and qb is None:\n            return False\n        if qa is not None and qb is not None:\n            b.cx(qb, qa); act(f, qa); b.cx(qb, qa)\n        else:\n            act(f, qa if qa is not None else qb)\n        return True\n\n    for j in range(h0 + 11):\n        ex = angfn(j)\n        if ex is None or ex % 2 == 0:\n            continue\n        b.reset(z)\n        has_r = j <= hiR\n        if has_r:\n            b.cx(R[j], z)\n        t8 = term(f8, j, 4, lambda f, q: b.ccx(f, q, z))\n        t16 = term(f16, j, 8, lambda f, q: b.ccx(f, q, z))\n        if not (has_r or t8 or t16):\n            continue\n        b.z_pow(z, ex)\n        m = b.alloc_bits(1)[0]\n        b.hmr(z, m)\n        b.push_condition(m)\n        if has_r:\n            b.z(R[j])\n        term(f8, j, 4, lambda f, q: b.cz(f, q))\n        term(f16, j, 8, lambda f, q: b.cz(f, q))\n        b.pop_condition()\n        b.free(km.array([m]))\n    b.free(km.array([z]))\n    for k, f, hi in reversed(shifts):\n        for i in range(0, hi + 1):\n            if (k, i) in empty:\n                b.cx(R[i + k], R[i]); b.del_and(f, R[i], R[i + k])\n            else:\n                b.cswap(f, R[i], R[i + k])\n\n\ndef mdel(b, address, groups):\n    """Measurement-based unlookup fix-up for several already-measured registers sharing one\n    8-bit address: applies prod_g (-1)^{m_g . table_g[addr]} with a 16-way one-hot of the low\n    nibble (14 ANDs, freed by measurement) and a unary iteration over the high nibble."""\n    lo, hi = list(address[:4]), list(address[4:8])\n    oh = [None] * 16\n    q0 = b.alloc_qubits(1)[0]\n    q1 = b.alloc_qubits(1)[0]\n    b.x(q0); b.cx(lo[0], q1); b.cx(q1, q0)\n    oh[0], oh[1] = q0, q1\n    made = []\n    for j in range(1, 4):\n        for e in range(1 << j):\n            n = b.alloc_qubits(1)[0]\n            b.init_and(oh[e], lo[j], n)\n            b.cx(n, oh[e])\n            oh[e + (1 << j)] = n\n            made.append((j, e, n))\n    with b.unary_iteration(km.array(hi)) as it:\n        for v, mu in it:\n            for l in range(16):\n                a = v * 16 + l\n                for bits, tab in groups:\n                    val = int(tab[a])\n                    k = 0\n                    while val:\n                        if val & 1:\n                            b.push_condition(bits[k])\n                            b.cz(mu, oh[l])\n                            b.pop_condition()\n                        val >>= 1\n                        k += 1\n    for j, e, n in reversed(made):\n        b.cx(n, oh[e])\n        b.del_and(oh[e], lo[j], n)\n        b.free(km.array([n]))\n    b.cx(q1, q0); b.cx(lo[0], q1); b.x(q0)\n    b.free(km.array([q0, q1]))\n\n\ndef measure(b, qs):\n    bits = b.alloc_bits(len(qs))\n    b.hmr(km.array(list(qs)), bits)\n    return bits\n\n\n# ---------------------------------------------------------------- nested windows for step B\ndef parse_plan(spec):\n    """\'15:9,8,7;12:6,5,4;9:3,2,1,0\' -> [(K, rows)] outer -> inner."""\n    out = []\n    for part in spec.split(\';\'):\n        K, rows = part.split(\':\')\n        out.append((int(K), [int(r) for r in rows.split(\',\')]))\n    return out\n\n\ndef sim_windows(tables, prm, lay, wins, cbits):\n    """Bit-exact simulation of big rows + nested windows + folds; True if L ends correct."""\n    a, p, xn, bounds = Fm.domains()\n    b = xn & 0x3FFF\n    C0, C1, C2 = tables[a, 0], tables[a, 1], tables[a, 2]\n    T = M.eval_T(C1, C2, b, prm)\n    Ltrue = lay.u[a] + (M.eval_Y(C0, T, b, prm) - C0)\n    LB = lay.LB\n    m = lambda k: (1 << k) - 1\n    L = lay.u[a].copy()\n    winrows = set(r for _, rs in wins for r in rs)\n    vals = {}\n    for i in prm.rowsB:\n        sig = 2 * ((b >> i) & 1) - 1\n        vals[i] = -sig * M.rd(T, prm.eB(i) + 1)\n    for i in prm.rowsB:\n        if i not in winrows:\n            L = (L + vals[i]) & m(LB)\n    cnt = []\n    for (K, rows), c in zip(wins, cbits):\n        cb = np.zeros_like(L)\n        for i in rows:\n            v = (L & m(K)) + (cb << K) + vals[i]\n            v &= m(K + c)\n            L = (L & ~m(K)) | (v & m(K))\n            cb = v >> K\n        cnt.append(cb)\n    for idx in reversed(range(len(wins))):\n        K, _ = wins[idx]\n        c = cbits[idx]\n        sval = cnt[idx] - ((cnt[idx] >> (c - 1)) & 1) * (1 << c)   # signed\n        if idx > 0:\n            Kp, _ = wins[idx - 1]\n            cp = cbits[idx - 1]\n            t = ((L >> K) & m(Kp - K)) + (cnt[idx - 1] << (Kp - K))\n            t = (t + sval) & m(Kp - K + cp)\n            L = (L & ~(m(Kp - K) << K)) | ((t & m(Kp - K)) << K)\n            cnt[idx - 1] = t >> (Kp - K)\n        else:\n            t = ((L >> K) + sval) & m(LB - K)\n            L = (L & m(K)) | (t << K)\n    return bool(np.array_equal(L, Ltrue))\n\n\ndef choose_cbits(tables, prm, lay, wins, cmax=3):\n    n = len(wins)\n    cb = [2] * n\n    while not sim_windows(tables, prm, lay, wins, cb):\n        if min(cb) >= cmax:\n            return None\n        cb = [c + 1 for c in cb]\n    for k in range(n):\n        if cb[k] > 1:\n            t = list(cb)\n            t[k] -= 1\n            if sim_windows(tables, prm, lay, wins, t):\n                cb = t\n    return cb\n\n\ndef win_step(bb, x, prm, op, L, wins, cbits, fwd, store, kbig=0, qcap=None):\n    b = bb.b\n\n    def row(i, win, k=0):\n        e = prm.eB(i) + 1\n        srcs = [op[q + e] if 0 <= q + e < len(op) else None for q in range(len(win))]\n        assert len(op) - e <= len(win), (\'window too small\', i, len(op) - e, len(win))\n        cin = op[e - 1] if 1 <= e <= len(op) else None\n        ctl = x[i]\n        if not fwd:\n            b.x(ctl)\n        for q in win:\n            b.cx(ctl, q)\n        if qcap:\n            need = b.num_allocated_qubits + len(win) - 2\n            k = max(0, need - qcap)\n            if k and cin is None:\n                k += 1\n        if k and all(isinstance(s_, km.q) for s_ in srcs[:k]) and k < len(win) - 1:\n            bb.add_ip(srcs, win, cin, k)\n        else:\n            bb.add(srcs, win, cin=cin)\n        for q in win:\n            b.cx(ctl, q)\n        if not fwd:\n            b.x(ctl)\n\n    winrows = set(r for _, rs in wins for r in rs)\n    big = [i for i in prm.rowsB if i not in winrows]\n\n    def fold(idx, sub):\n        K, _ = wins[idx]\n        cq = store[idx]\n        c = len(cq)\n        if idx > 0:\n            Kp, _ = wins[idx - 1]\n            tgt = list(L[K:Kp]) + list(store[idx - 1])\n        else:\n            tgt = list(L[K:])\n        src = list(cq) + [cq[-1]] * (len(tgt) - c)\n        bb.add(src[:len(tgt)], tgt, subtract=sub)\n\n    if fwd:\n        for i in big:\n            row(i, list(L), kbig)\n        for idx, (K, rows) in enumerate(wins):\n            cq = list(b.alloc_qubits(cbits[idx]))\n            store.append(cq)\n            for i in rows:\n                row(i, list(L[:K]) + cq)\n        for idx in reversed(range(len(wins))):\n            fold(idx, False)\n    else:\n        for idx in range(len(wins)):\n            fold(idx, True)\n        for idx in reversed(range(len(wins))):\n            K, rows = wins[idx]\n            for i in reversed(rows):\n                row(i, list(L[:K]) + store[idx])\n            b.free(km.array(store[idx]))\n        store.clear()\n        for i in reversed(big):\n            row(i, list(L), kbig)\n\n\ndef build_hsplit(tables, prm, o: Opts, lay, angs):\n    """sd-mode circuit with the H/L output split (f1 parked in x_n[21], fused phasing)."""\n    bb = B()\n    bb.cap = o.cap\n    b = bb.b\n    x = b.create_quantum_register(22, name=\'x\')\n    f1, f2, f4, f8, f16 = list(b.alloc_qubits(5))\n    F = {\'f1\': f1}\n\n    def thermo_compute():\n        f1_ = F[\'f1\']\n        th = b.alloc_qubits(21)\n        b.x(x[1:22]); b.cx(x[21], th[0])\n        for k in range(1, 21):\n            b.init_and(th[k - 1], x[21 - k], th[k])\n        for k in range(1, 22):\n            q = th[k - 1]\n            b.cx(q, f1_)\n            if k % 2 == 0:\n                b.cx(q, f2)\n            if k % 4 == 0:\n                b.cx(q, f4)\n            if k % 8 == 0:\n                b.cx(q, f8)\n            if k == 16:\n                b.cx(q, f16)\n        for k in range(20, 0, -1):\n            b.del_and(th[k - 1], x[21 - k], th[k])\n        b.cx(x[21], th[0]); b.x(x[1:22])\n        b.free(th)\n\n    def norm(fwd):\n        stages = [(16, f16), (8, f8), (4, f4), (2, f2), (1, F[\'f1\'])]\n        for k, f in (stages if fwd else reversed(stages)):\n            idx = range(21 - k, -1, -1) if fwd else range(0, 22 - k)\n            for i in idx:\n                b.cswap(f, x[i], x[i + k])\n\n    bb.label = \'thermo\'\n    thermo_compute()\n    bb.label = \'norm\'\n    norm(True)\n    b.cx(f1, x[21]); b.x(x[21]); b.cx(x[21], f1)\n    b.free(km.array([f1]))\n    address = km.array(list(x[14:21]) + [x[21]])\n\n    nT, n2, LB, nH = prm.nT, prm.F2 - 1, lay.LB, lay.nH\n    Lr = b.alloc_qubits(LB)\n    Hr = b.alloc_qubits(nH)\n    Tr = b.alloc_qubits(nT)\n    C2r = b.alloc_qubits(n2)\n    target = km.array(list(Lr) + list(Hr) + list(Tr) + list(C2r))\n    packed = [int(lay.u[a]) | (int(lay.H[a]) << LB) | (int(tables[a, 1]) << (LB + nH)) | (int(tables[a, 2]) << (LB + nH + nT))\n              for a in range(256)]\n    bb.label = \'lookup\'\n    b.init_lookup(table=packed, address=address, target=target)\n    bb.note(\' lookup\')\n    flags4 = (f2, f4, f8, f16)\n\n    def angfn(ang, off):\n        def g(j):\n            a = int(ang[off + j]) % (1 << 64) if off + j < len(ang) else 0\n            return None if a == 0 else Fraction(2 * a, 1 << 64)\n        return g\n\n    # phase H (+ the constant 1/2 bit) right away, then free H by measurement\n    pad = b.alloc_qubits(lay.nHf - nH) if lay.nHf > nH else []\n    cq = b.alloc_qubits(1)[0]\n    b.x(cq)\n    ext = b.alloc_qubits(3)\n    RH = list(Hr) + list(pad) + [cq] + list(ext)\n    bb.label = \'Hphase\'\n    fused_phase(bb, RH, lay.nHf, angfn(angs[0], lay.S - prm.G0), flags4)\n    b.free(ext)\n    b.x(cq)\n    b.free(km.array([cq]))\n    if len(pad):\n        b.free(pad)\n    Htab = [int(lay.H[a]) for a in range(256)]\n    assert o.mdel\n    mH = measure(b, Hr)\n    b.free(Hr)\n\n    # Horner\n    WA = o.WA if o.WA is not None else nT\n    gA = b.alloc_qubits(o.gA) if WA < nT else []\n    bb.label = \'A\'\n    sd_step(bb, x, prm.rowsA, C2r, Tr, prm.eA, WA, gA, True)\n    bb.label = \'B\'\n    wstore = []\n    if o.wins:\n        win_step(bb, x, prm, Tr, Lr, o.wins, o.wcb, True, wstore, o.kbig, o.qcap)\n    else:\n        sd_step(bb, x, prm.rowsB, Tr, Lr, prm.eB, LB, [], True)\n    # phase L\n    ext = b.alloc_qubits(3)\n    RL = list(Lr[prm.G0:]) + list(ext)\n    bb.label = \'Lphase\'\n    fused_phase(bb, RL, LB - prm.G0 - 1, angfn(angs[1], 0), flags4)\n    b.free(ext)\n    bb.label = \'B-1\'\n    if o.wins:\n        win_step(bb, x, prm, Tr, Lr, o.wins, o.wcb, False, wstore, o.kbig, o.qcap)\n    else:\n        sd_step(bb, x, prm.rowsB, Tr, Lr, prm.eB, LB, [], False)\n    bb.label = \'A-1\'\n    sd_step(bb, x, prm.rowsA, C2r, Tr, prm.eA, WA, gA, False)\n    if gA:\n        b.free(gA)\n    utab = [int(lay.u[a]) | (int(tables[a, 1]) << LB) | (int(tables[a, 2]) << (LB + nT)) for a in range(256)]\n    tgt2 = km.array(list(Lr) + list(Tr) + list(C2r))\n    bb.label = \'unlookup\'\n    mR = measure(b, tgt2)\n    b.free(tgt2)\n    mdel(b, address, [(mH, Htab), (mR, utab)])\n    nf1 = b.alloc_qubits(1)[0]\n    b.cx(x[21], nf1); b.x(x[21]); b.cx(nf1, x[21])\n    F[\'f1\'] = nf1\n    # stage-wise un-normalization; each flag equals [top d bits zero] of the restored state,\n    # so it is cleared by HMR + a conditional multi-controlled Z (avg half the Toffolis)\n    bb.label = \'unnorm\'\n    for d, f in [(1, nf1), (2, f2), (4, f4), (8, f8), (16, f16)]:\n        for i in range(0, 22 - d):\n            b.cswap(f, x[i], x[i + d])\n        top = list(x[22 - d:22])\n        if d == 1:\n            b.x(f); b.cx(x[21], f)\n            continue\n        m = b.alloc_bits(1)[0]\n        b.hmr(f, m)\n        b.push_condition(m)\n        b.x(km.array(top))\n        if d == 2:\n            b.cz(top[0], top[1])\n        else:\n            anc = b.alloc_qubits(d - 2)\n            b.init_and(top[0], top[1], anc[0])\n            for j in range(1, d - 2):\n                b.init_and(anc[j - 1], top[j + 1], anc[j])\n            b.cz(anc[d - 3], top[d - 1])\n            for j in reversed(range(1, d - 2)):\n                b.del_and(anc[j - 1], top[j + 1], anc[j])\n            b.del_and(top[0], top[1], anc[0])\n            b.free(anc)\n        b.x(km.array(top))\n        b.pop_condition()\n        b.free(km.array([m]))\n    b.free(km.array([nf1, f2, f4, f8, f16]))\n    return b.finish_circuit(), bb.peak\n', 'invsqrt/calib.py': '"""H/L output split layout and LP calibration of the rotation angles.\n\nY\' = H 2^S + L with H a pure table word and L = u + D (D = the Horner correction) kept\nin [0, 2^LB). Each register is phased through a shift register (positions j weigh\n2^(j - R0 - 10) turns exactly); the non-Clifford, non-T angles are re-optimised by a\ncutting-plane LP to maximise the minimum margin tol(x) - |error(x)| over all legal x.\nAngles are integers in units of 2^-64 turns, so the final check is exact.\n\nPorted from marsyas\'s Apache-2.0 notebook (hsplit.py and calib.py there; see the package\ndocstring; the LP calibration idea is credited there to lightningv08, the H/L split to\nanazemcev). change: the reference arrays are passed in instead of read from a module\ncache; dead code paths are dropped.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nfrom scipy.optimize import linprog\n\nfrom . import fit as Fm\nfrom . import model as M\n\n\nclass Layout:\n    pass\n\n\ndef layout(tables, prm, LB, S):\n    a, p, xn, bounds = Fm.domains()\n    b = xn & 0x3FFF\n    C0, C1, C2 = tables[a, 0], tables[a, 1], tables[a, 2]\n    T = M.eval_T(C1, C2, b, prm)\n    D = M.eval_Y(C0, T, b, prm) - C0\n    dmin = np.minimum.reduceat(D, bounds[:-1])\n    dmax = np.maximum.reduceat(D, bounds[:-1])\n    u = np.zeros(256, np.int64)\n    H = np.zeros(256, np.int64)\n    for k in range(256):\n        c0 = int(tables[k, 0])\n        base = c0 % (1 << S)\n        j = 0\n        while base + j * (1 << S) + dmin[k] < 0:\n            j += 1\n        uk = base + j * (1 << S)\n        if uk + dmax[k] >= (1 << LB) or c0 - uk < 0:\n            return None\n        u[k] = uk\n        H[k] = (c0 - uk) >> S\n    lay = Layout()\n    lay.LB, lay.S, lay.u, lay.H = LB, S, u, H\n    lay.nHf = prm.F0 - 1 - S          # H register span up to the constant bit\n    lay.nH = max(int(H.max()).bit_length(), 1)\n    assert lay.nH <= lay.nHf\n    return lay\n\n\ndef phases(V, ang):\n    acc = np.zeros(len(V), dtype=np.uint64)\n    for j, a in enumerate(ang):\n        a = int(a) & M.MASK64\n        if a == 0:\n            continue\n        acc += ((V >> j) & 1).astype(np.uint64) * np.uint64(a)\n    return acc\n\n\ndef regs(tables, prm, lay, xs):\n    """[(shifted register value, offset, top index)] for the H and L phase registers."""\n    t, xn, p, s = M.decompose(xs)\n    a = (p << 7) | ((xn >> 14) & 127)\n    b = xn & 0x3FFF\n    C0, C1, C2 = tables[a, 0], tables[a, 1], tables[a, 2]\n    T = M.eval_T(C1, C2, b, prm)\n    Y = M.eval_Y(C0, T, b, prm)\n    L = lay.u[a] + (Y - C0)\n    VH = (lay.H[a] + (1 << lay.nHf)) << s\n    VL = (L >> prm.G0) << s\n    offH = lay.S - prm.G0\n    return [(VH << offH, offH, lay.nHf), (VL, 0, lay.LB - prm.G0 - 1)]\n\n\ndef phases_multi(R, angs):\n    acc = np.zeros(len(R[0][0]), dtype=np.uint64)\n    for (V, off, h0), ang in zip(R, angs):\n        acc += phases(V, ang)\n    return acc\n\n\ndef exact_angles(prm):\n    R0 = prm.F0 - prm.G0\n    return [int(1 << (64 + j - R0 - 10)) for j in range(R0 + 10)]\n\n\ndef spans(prm, R):\n    R0 = prm.F0 - prm.G0\n    return [[pp for pp in range(off, off + h0 + 11) if pp <= R0 + 6] for V, off, h0 in R]\n\n\ndef check_multi(tables, prm, lay, angs, ref):\n    target, tol = ref\n    xs = np.arange(1, M.MAX_X + 1, dtype=np.int64)\n    R = regs(tables, prm, lay, xs)\n    ph = phases_multi(R, angs)\n    err = (ph - target).view(np.int64)\n    used = np.abs(err).astype(np.float64)\n    return float((used / tol).max()), float((tol.astype(np.float64) - used).min()), err, tol, R\n\n\ndef calibrate_multi(tables, prm, lay, ref, drop=1, iters=12, verbose=False):\n    R0 = prm.F0 - prm.G0\n    ex = exact_angles(prm)\n    xs = np.arange(1, M.MAX_X + 1, dtype=np.int64)\n    R = regs(tables, prm, lay, xs)\n    sp = spans(prm, R)\n    angs = [list(ex) for _ in R]\n    var = []\n    for r, (V, off, h0) in enumerate(R):\n        for pp in range(R0 + 10):\n            if not (off <= pp <= off + h0 + 10):\n                angs[r][pp] = 0\n        pos = sp[r]\n        if r == 1:   # drop the lowest L positions\n            for pp in pos[:drop]:\n                angs[r][pp] = 0\n            pos = pos[drop:]\n        var += [(r, pp) for pp in pos]\n    worst, margin, err, tol, _ = check_multi(tables, prm, lay, angs, ref)\n    if verbose:\n        print(\'start\', worst, margin, flush=True)\n    bits = np.stack([((R[r][0] >> pp) & 1).astype(np.float32) for r, pp in var], axis=1)\n    tolf = tol.astype(np.float64)\n    errf = err.astype(np.float64)\n    act = np.argsort(tolf - np.abs(errf))[:20000]\n    best = None\n    S_ = 2.0 ** 20\n    for it in range(iters):\n        A = bits[act].astype(np.float64)\n        e = errf[act] / S_\n        tl = tolf[act] / S_\n        n = len(var)\n        c = np.zeros(n + 1)\n        c[-1] = -1\n        one = np.ones_like(tl)\n        Aub = np.r_[np.c_[A, one], np.c_[-A, one]]\n        bub = np.r_[tl - e, tl + e]\n        res = linprog(c, A_ub=Aub, b_ub=bub, bounds=[(-2**20, 2**20)] * n + [(None, None)], method=\'highs\')\n        if res.x is None:\n            break\n        d = np.round(res.x[:n] * S_).astype(np.int64)\n        tot = errf + bits @ d.astype(np.float64)\n        slack = tolf - np.abs(tot)\n        w = 2.0 if slack.min() <= 0 else 1.0 / slack.min()\n        if verbose:\n            print(f\'it {it} minslack {slack.min():.4g}\', flush=True)\n        if best is None or w < best[0]:\n            best = (w, d.copy())\n        act2 = np.union1d(act, np.argsort(slack)[:5000])\n        if len(act2) == len(act):\n            break\n        act = act2\n    if best is None:\n        return None\n    d = best[1]\n    for k, (r, pp) in enumerate(var):\n        angs[r][pp] = int(angs[r][pp]) + int(d[k])\n    worst, margin, _, _, _ = check_multi(tables, prm, lay, angs, ref)\n    return angs, worst, margin, len(var)\n', 'invsqrt/check.py': '"""Simulate a built circuit on sample x with kickmix and compare phases bit-exactly with\nthe model; report Q, mean executed Toffolis, rotations and the projected cost.\n\nPorted from marsyas\'s Apache-2.0 notebook (check.py there; see the package docstring).\nchange: the model phase is passed in as a function instead of a module global.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport kickmix as km\n\nfrom . import model as M\n\nREFERENCE_COST = 2076774.233715282\n\n\ndef to_bits(v, w):\n    return (v[None, :] >> np.arange(w, dtype=np.uint64)[:, None]) & 1 == 1\n\n\ndef from_bits(bits):\n    return (bits.astype(np.uint64) << np.arange(len(bits), dtype=np.uint64)[:, None]).sum(axis=0)\n\n\ndef half_turns_to_units(h):\n    n, d = h.as_integer_ratio()\n    return (((n << 64) // d + 1) >> 1) & M.MASK64\n\n\ndef sim_check(circ, phase_fn, nbatch=16, seed=1, batch=256):\n    regs = circ.register_data\n    xr = km.array(list(regs[\'x\']))\n    xset = set(regs[\'x\'])\n    scratch = km.array([km.q(i) for i in range(circ.num_qubits) if km.q(i) not in xset])\n    rng = np.random.default_rng(seed)\n    sim = km.Simulator(batch_size=batch, seed=seed, debug_print=False, counting_operations=True)\n    shots = 0\n    for k in range(nbatch):\n        xs = rng.integers(1, M.MAX_X + 1, batch, dtype=np.uint64)\n        if k == 0:\n            edges = [1, 2, 3, M.MAX_X] + [v for p in range(1, 22) for v in (2**p - 1, 2**p, 2**p + 1) if v <= M.MAX_X]\n            xs[:len(edges)] = edges\n        sim.clear_for_shot()\n        sim.write_across_shots(xr, to_bits(xs, 22))\n        sim.do(circ)\n        assert np.array_equal(from_bits(sim.read_across_shots(xr)), xs), \'x not restored\'\n        dirty = sim.read_across_shots(scratch).any(axis=1)\n        assert not dirty.any(), f\'scratch dirty {np.flatnonzero(dirty)[:5]}\'\n        ph = np.array([half_turns_to_units(sim.read_shot_phase(i)) for i in range(batch)], dtype=np.uint64)\n        md = phase_fn(xs.astype(np.int64))\n        if not np.array_equal(ph, md):\n            i = int(np.flatnonzero(ph != md)[0])\n            raise AssertionError(f\'mismatch x={xs[i]} circ={ph[i]} model={md[i]}\')\n        shots += batch\n    st = sim.operation_statistics()\n    return st.num_toffoli_like / shots, st.num_t_like / shots, st.num_z_pow(min_clifford_hierarchy_level=4) / shots\n\n\ndef report(circ, phase_fn, min_margin, nbatch=16):\n    tof, tl, nrot = sim_check(circ, phase_fn, nbatch=nbatch)\n    out = {\'Q\': circ.num_qubits, \'toffoli_sampled_mean\': tof, \'t\': tl, \'rot\': nrot,\n           \'max_toffoli\': circ.operation_statistics().num_toffoli_like}\n    if min_margin and min_margin > 0:\n        T = tl + M.rotation_cost(nrot, min_margin)\n        out[\'C\'] = tof + T / 4\n        out[\'cost\'] = out[\'Q\'] * out[\'C\']\n        out[\'ratio\'] = REFERENCE_COST / out[\'cost\']\n    return out\n', 'invsqrt/exact.py': '"""Exact-domain post-pass: track every qubit\'s classical value on all 3,133,452 legal inputs;\nToffoli-like gates whose controls are provably constant or equal/opposite become\nCNOT/CZ/SWAP or are deleted.\n\nPorted from marsyas\'s Apache-2.0 notebook (exact.py there; idea credited to Artem /\nanazemcev; see the package docstring). change: works on a kmx text file in a caller-given\ndirectory instead of a mktemp path, and returns the statistics.\n\nSoundness: value ops (X, CX, CCX, SWAP, CSWAP, R) under an inline classical condition are\nrefused; a PUSH_CONDITION block must be value-neutral (checked), so tracking it as if it\nalways ran gives the right values after the block.\n"""\nfrom __future__ import annotations\n\nimport os\nimport re\n\nimport numpy as np\nimport kickmix as km\n\nfrom . import model as M\n\nVALUE_OPS = {\'X\', \'CX\', \'CCX\', \'SWAP\', \'CSWAP\', \'R\'}\n\n\ndef run(circ: km.Circuit, work_dir: str):\n    os.makedirs(work_dir, exist_ok=True)\n    tmp = os.path.join(work_dir, \'_exact_in.kmx\')\n    circ.to_file(tmp, format=\'kmx\')\n    with open(tmp, encoding=\'utf-8\') as f:\n        lines = f.read().split(\'\\n\')\n    os.remove(tmp)\n    xq = [int(re.findall(r\'\\d+\', repr(q))[-1]) for q in circ.register_data[\'x\']]\n    exp = []\n    for line in lines:\n        tok = line.split()\n        if tok and tok[0] in (\'CCX\', \'CCZ\', \'CSWAP\'):\n            cond = \'\'\n            if \'if\' in tok:\n                k = tok.index(\'if\')\n                cond = \' \' + \' \'.join(tok[k:])\n                tok = tok[:k]\n            qs = tok[1:]\n            if len(qs) > 3:\n                for i in range(0, len(qs), 3):\n                    exp.append(f\'{tok[0]} \' + \' \'.join(qs[i:i + 3]) + cond)\n                continue\n        exp.append(line)\n    lines = exp\n    N = M.MAX_X\n    xs = np.arange(1, N + 1, dtype=np.int64)\n    val = {}\n\n    def V(q):\n        if q not in val:\n            val[q] = np.zeros(N, dtype=bool)\n        return val[q]\n\n    for i, q in enumerate(xq):\n        val[q] = ((xs >> i) & 1).astype(bool)\n    out = []\n    stats = {\'ccx_del\': 0, \'ccx_cx\': 0, \'ccz_del\': 0, \'ccz_cz\': 0, \'cswap_del\': 0, \'cswap_swap\': 0}\n    snaps = []\n\n    def const(v):\n        if not v.any():\n            return 0\n        if v.all():\n            return 1\n        return None\n\n    for line in lines:\n        tok = line.split()\n        if not tok:\n            out.append(line)\n            continue\n        op = tok[0]\n        cond = \'\'\n        if \'if\' in tok:\n            k = tok.index(\'if\')\n            cond = \' \' + \' \'.join(tok[k:])\n            tok = tok[:k]\n        qs = [int(t[1:]) for t in tok[1:] if t.startswith(\'q\')]\n        if op == \'PUSH_CONDITION\':\n            snaps.append({})\n            out.append(line)\n            continue\n        if op == \'POP_CONDITION\':\n            for q, v0 in snaps.pop().items():\n                if not np.array_equal(v0, V(q)):\n                    raise RuntimeError(\'conditional block is not value-neutral\')\n            out.append(line)\n            continue\n        if op in VALUE_OPS or op == \'HMR\':\n            if cond:\n                raise RuntimeError(\'conditional value op: \' + line)\n            if snaps:\n                for q in qs:\n                    for d in snaps:\n                        if q not in d:\n                            d[q] = V(q).copy()\n        if op == \'CCX\':\n            a, b_, t = qs\n            va, vb = V(a), V(b_)\n            ca, cb = const(va), const(vb)\n            if ca == 0 or cb == 0 or np.array_equal(va, ~vb):\n                stats[\'ccx_del\'] += 1\n            elif ca == 1:\n                out.append(f\'CX q{b_} q{t}{cond}\')\n                stats[\'ccx_cx\'] += 1\n                V(t)[:] ^= vb\n            elif cb == 1 or np.array_equal(va, vb):\n                out.append(f\'CX q{a} q{t}{cond}\')\n                stats[\'ccx_cx\'] += 1\n                V(t)[:] ^= va\n            else:\n                out.append(line)\n                V(t)[:] ^= va & vb\n            continue\n        if op == \'CCZ\':\n            a, b_, t = qs\n            vs = [V(a), V(b_), V(t)]\n            cs = [const(v) for v in vs]\n            if 0 in cs:\n                stats[\'ccz_del\'] += 1\n                continue\n            done = False\n            for i in range(3):\n                for j in range(i + 1, 3):\n                    if np.array_equal(vs[i], ~vs[j]):\n                        stats[\'ccz_del\'] += 1\n                        done = True\n                        break\n                if done:\n                    break\n            if done:\n                continue\n            for i in range(3):\n                if cs[i] == 1:\n                    o = [qs[k] for k in range(3) if k != i]\n                    out.append(f\'CZ q{o[0]} q{o[1]}{cond}\')\n                    stats[\'ccz_cz\'] += 1\n                    done = True\n                    break\n            if done:\n                continue\n            for i in range(3):\n                for j in range(i + 1, 3):\n                    if np.array_equal(vs[i], vs[j]) and not done:\n                        k = 3 - i - j\n                        out.append(f\'CZ q{qs[i]} q{qs[k]}{cond}\')\n                        stats[\'ccz_cz\'] += 1\n                        done = True\n            if not done:\n                out.append(line)\n            continue\n        if op == \'CSWAP\':\n            cq, a, b_ = qs\n            vc, va, vb = V(cq), V(a), V(b_)\n            cc = const(vc)\n            if cc == 0 or np.array_equal(va, vb):\n                stats[\'cswap_del\'] += 1\n                continue\n            if cc == 1:\n                out.append(f\'SWAP q{a} q{b_}\')\n                stats[\'cswap_swap\'] += 1\n                val[a], val[b_] = vb.copy(), va.copy()\n                continue\n            out.append(line)\n            m = vc & (va ^ vb)\n            va ^= m\n            vb ^= m\n            continue\n        out.append(line)\n        if op == \'X\':\n            for q in qs:\n                V(q)[:] ^= True\n        elif op == \'CX\':\n            for a, t in zip(qs[0::2], qs[1::2]):\n                V(t)[:] ^= V(a)\n        elif op == \'SWAP\':\n            for a, t in zip(qs[0::2], qs[1::2]):\n                val[a], val[t] = V(t).copy(), V(a).copy()\n        elif op in (\'R\', \'HMR\'):\n            for q in qs:\n                V(q)[:] = False\n    c2 = km.Circuit(\'\\n\'.join(out))\n    return c2, stats\n', 'invsqrt/fit.py': '"""Fit integer coefficient tables against the exact truncated arithmetic of model.py.\n\nPer segment: continuous minimax (LP) quadratic in the centred delta, then an integer\nneighbourhood search over (C1, C2) with the best C0 for each, scored by the max\nrelative error of Y over exactly the (p, x_n) inputs that occur.\n\nPorted from marsyas\'s Apache-2.0 notebook (see package docstring). change: the worker\npool uses the \'spawn\' start method (Windows) and receives each segment\'s inputs\nexplicitly instead of through a module global set before a fork; only the G0 > 0 / sd\npaths the 13.94x build uses are kept.\n"""\nfrom __future__ import annotations\n\nimport concurrent.futures as cf\nimport multiprocessing as mp\n\nimport numpy as np\nfrom scipy.optimize import linprog\n\nfrom . import model as M\n\n_D = None\n\n\ndef domains():\n    """Distinct (p, x_n) over all legal x, sorted by segment address, and segment bounds."""\n    global _D\n    if _D is not None:\n        return _D\n    xs = np.arange(1, M.MAX_X + 1, dtype=np.int64)\n    t, xn, p, s = M.decompose(xs)\n    key = np.unique((p << 22) | xn)\n    p = key >> 22\n    xn = key & ((1 << 22) - 1)\n    a = (p << 7) | ((xn >> 14) & 127)\n    order = np.argsort(a, kind=\'stable\')\n    a, p, xn = a[order], p[order], xn[order]\n    bounds = np.searchsorted(a, np.arange(257))\n    _D = (a, p, xn, bounds)\n    return _D\n\n\ndef ytrue(p, xn):\n    return np.where(p == 1, 1.0, 2 ** -0.5) * 2 ** 10.5 / np.sqrt(xn.astype(np.float64))\n\n\ndef lp_fit(dc, y):\n    """Minimax relative fit y ~ c0 - c1 dc + c2 dc^2 on 600 sample points."""\n    idx = np.unique(np.r_[np.linspace(0, len(dc) - 1, 600).astype(int)])\n    d, yy = dc[idx], y[idx]\n    A1 = np.c_[np.ones_like(d), -d, d * d, -yy]\n    A2 = np.c_[-np.ones_like(d), d, -d * d, -yy]\n    A = np.r_[A1, A2]\n    bvec = np.r_[yy, -yy]\n    r = linprog([0, 0, 0, 1], A_ub=A, b_ub=bvec, bounds=[(None, None)] * 3 + [(0, None)], method=\'highs\')\n    return r.x[:3]\n\n\ndef best_C0(R, ytgt, w, top):\n    d = R - ytgt\n    c = -0.5 * (d.max() + d.min())\n    best = None\n    cands = [np.floor(c) - 1, np.floor(c), np.floor(c) + 1, np.floor(c) + 2]\n    hi = top - 1 - R.max()\n    cands = [min(v, hi) for v in cands]\n    for C0 in cands:\n        sc = np.max(np.abs(C0 + R - ytgt) * w)\n        if best is None or sc < best[0]:\n            best = (sc, int(C0))\n    return best\n\n\ndef best_C0_g(R, ytgt, w, G0, top):\n    d = R - ytgt\n    c = int(np.floor(-0.5 * (d.max() + d.min()) + (1 << G0) / 2))\n    best = None\n    hi = int(top - 1 - R.max())\n    cands = sorted(set(min(v, hi) for v in range(c - (1 << G0), c + (1 << G0) + 1)))\n    for C0 in cands:\n        e = (((C0 + R) >> G0) << G0) - ytgt\n        sc = np.max(np.abs(e) * w)\n        if best is None or sc < best[0]:\n            best = (sc, C0)\n    return best\n\n\ndef fit_segment(p, xn, prm: M.Params, rad1=6, rad2=3):\n    b = xn & 0x3FFF\n    dc = (b - 8191.5) * 2.0 ** -21\n    y = ytrue(p, xn)\n    c0, c1, c2 = lp_fit(dc, y)\n    ytgt = (y - 0.5) * 2 ** prm.F0\n    w = 1.0 / (y * 2 ** prm.F0) * 2 ** 24   # error / tolerance (approx)\n    top = 1 << (prm.F0 - 1)\n    zeros = np.zeros(len(b), np.int64)\n    cache = {}\n\n    def ev(C1, C2):\n        key = (C1, C2)\n        if key in cache:\n            return cache[key]\n        T = M.eval_T(zeros + C1, zeros + C2, b, prm)\n        if T.min() < 0 or T.max() >= (1 << prm.nT) or C1 >= (1 << prm.nT):\n            r = (np.inf, 0)\n        else:\n            R = M.eval_Y(zeros, T, b, prm)\n            r = best_C0(R, ytgt, w, top) if prm.G0 == 0 else best_C0_g(R, ytgt, w, prm.G0, top)\n        cache[key] = r\n        return r\n\n    k1 = int(round(c1 * 2 ** prm.FT))\n    k2 = int(round(c2 * 2 ** prm.F2))\n    best = None\n    for C2 in range(k2 - rad2, k2 + rad2 + 1):\n        for C1 in range(k1 - rad1, k1 + rad1 + 1):\n            sc, C0 = ev(C1, C2)\n            if best is None or sc < best[0]:\n                best = (sc, C0, C1, C2)\n    improved = True\n    while improved:\n        improved = False\n        _, _, C1b, C2b = best\n        for d2 in (-1, 0, 1):\n            for d1 in range(-3, 4):\n                sc, C0 = ev(C1b + d1, C2b + d2)\n                if sc < best[0] - 1e-12:\n                    best = (sc, C0, C1b + d1, C2b + d2)\n                    improved = True\n    return best\n\n\ndef _work(args):\n    seg, p, xn, prm, rad1, rad2 = args\n    if len(p) == 0:\n        return seg, (0.0, 0, 0, 0)\n    return seg, fit_segment(p, xn, prm, rad1, rad2)\n\n\ndef fit_all(prm: M.Params, rad1=6, rad2=3, workers=8):\n    """(256, 3) int64 table [C0, C1, C2] per segment address, and the worst approx score."""\n    a, p, xn, bounds = domains()\n    tasks = [(s, p[bounds[s]:bounds[s + 1]], xn[bounds[s]:bounds[s + 1]], prm, rad1, rad2) for s in range(256)]\n    tables = np.zeros((256, 3), dtype=np.int64)\n    worst = 0.0\n    if workers <= 1:\n        results = map(_work, tasks)\n    else:\n        ex = cf.ProcessPoolExecutor(max_workers=workers, mp_context=mp.get_context(\'spawn\'))\n        results = ex.map(_work, tasks)\n    for seg, (sc, C0, C1, C2) in results:\n        tables[seg] = (C0, C1, C2)\n        worst = max(worst, sc)\n    if workers > 1:\n        ex.shutdown()\n    return tables, worst\n', 'invsqrt/generate.py': '"""End-to-end invsqrt generator driven by a JSON config.\n\nfit tables (cached) -> H/L layout -> LP angle calibration (cached) -> exact all-x model\ncheck -> build -> kickmix sample check against the model -> exact-domain post-pass ->\nkickmix sample check again -> write .kmb and a report.\n\nConfig keys (all required unless noted):\n  F0, FT, F2, G0           model precisions (model.Params)\n  dropA, dropB             rows left out of step A / B (lists)\n  LB, S                    H/L split: L width and H shift\n  drop                     lowest L phase positions given no rotation\n  wins                     nested-window plan string, e.g. "17:11,10;15:9,8"\n  kbig, qcap               (optional) in-place adder prefixes for step B\n  exact_pass               (optional, default true) run exact.py on the built circuit\n  rad1, rad2               (optional) fit neighbourhood radii (default 6, 3)\n\nThe pipeline structure follows marsyas\'s Apache-2.0 run.py/hsplit.py main (see package\ndocstring); this file is ours.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport io\nimport json\nimport os\nimport pickle\nimport sys\nimport time\n\nimport numpy as np\n\nfrom . import build as Bd\nfrom . import calib as Ca\nfrom . import check as Ck\nfrom . import exact as Ex\nfrom . import fit as Fm\nfrom . import model as M\n\n\ndef params_from(cfg) -> M.Params:\n    nr = 14\n    return M.Params(F0=cfg[\'F0\'], FT=cfg[\'FT\'], F2=cfg[\'F2\'], G0=cfg[\'G0\'], tcap=cfg.get(\'tcap\', True),\n                    rowsA=tuple(i for i in range(nr) if i not in cfg.get(\'dropA\', [])),\n                    rowsB=tuple(i for i in range(nr) if i not in cfg.get(\'dropB\', [])))\n\n\ndef tag(prm: M.Params, cfg) -> str:\n    dA = \'\'.join(f\'{i:x}\' for i in range(14) if i not in prm.rowsA)\n    dB = \'\'.join(f\'{i:x}\' for i in range(14) if i not in prm.rowsB)\n    return f"{prm.F0}_{prm.FT}_{prm.F2}_{prm.G0}_sd{\'_tc\' if prm.tcap else \'\'}_a{dA}_b{dB}_r{cfg.get(\'rad1\', 6)}{cfg.get(\'rad2\', 3)}"\n\n\ndef kmb_sha256(circ) -> str:\n    buf = io.BytesIO()\n    circ.to_file(buf, format=\'kmb\')\n    return hashlib.sha256(buf.getvalue()).hexdigest()\n\n\ndef run(cfg: dict, work: str, out_path: str | None = None, workers: int = 8, nbatch: int = 8, log=print):\n    os.makedirs(work, exist_ok=True)\n    t0 = time.time()\n    prm = params_from(cfg)\n    tg = tag(prm, cfg)\n    ref = M.reference(os.path.join(work, \'ref.npz\'))\n    tpath = os.path.join(work, f\'tab_{tg}.npy\')\n    if os.path.exists(tpath):\n        tables = np.load(tpath)\n    else:\n        tables, _ = Fm.fit_all(prm, rad1=cfg.get(\'rad1\', 6), rad2=cfg.get(\'rad2\', 3), workers=workers)\n        np.save(tpath, tables)\n    log(f\'tables {time.time() - t0:.1f}s\')\n    lay = Ca.layout(tables, prm, cfg[\'LB\'], cfg[\'S\'])\n    if lay is None:\n        raise ValueError(\'layout infeasible\')\n    drop = cfg.get(\'drop\', 1)\n    cpath = os.path.join(work, f\'hang_{tg}_L{lay.LB}_S{lay.S}_d{drop}.pkl\')\n    if os.path.exists(cpath):\n        with open(cpath, \'rb\') as f:\n            angs, worst, margin, nrot = pickle.load(f)\n    else:\n        res = Ca.calibrate_multi(tables, prm, lay, ref, drop=drop)\n        if res is None:\n            raise ValueError(\'calibration LP failed\')\n        angs, worst, margin, nrot = res\n        with open(cpath, \'wb\') as f:\n            pickle.dump((angs, worst, margin, nrot), f)\n    log(f\'calibration worst {worst} margin {margin} nrot {nrot} ({time.time() - t0:.1f}s)\')\n    model = {\'worst\': worst, \'min_margin\': int(margin), \'nrot_model\': nrot, \'pass\': bool(worst < 1 and margin > 0)}\n    if not model[\'pass\']:\n        return {\'model\': model, \'cfg\': cfg}\n    a, p, xn, bounds = Fm.domains()\n    W = M.window_ranges1(tables, prm, xn, p)\n    o = Bd.Opts(WA=W[\'A\'], gA=1, mdel=True)\n    o.wins = Bd.parse_plan(cfg[\'wins\']) if cfg.get(\'wins\') else None\n    o.kbig = int(cfg.get(\'kbig\', 0))\n    o.qcap = cfg.get(\'qcap\')\n    if o.wins:\n        o.wcb = cfg.get(\'wcb\') or Bd.choose_cbits(tables, prm, lay, o.wins)\n        if o.wcb is None:\n            raise ValueError(\'no window counter bits fit\')\n    log(f\'windows A {W}, wcb {o.wcb}\')\n    circ, peak = Bd.build_hsplit(tables, prm, o, lay, angs)\n    phase_fn = lambda xs: Ca.phases_multi(Ca.regs(tables, prm, lay, xs), angs)\n    rep_raw = Ck.report(circ, phase_fn, margin, nbatch=nbatch)\n    rep_raw[\'peak\'] = peak\n    rep_raw[\'sha256\'] = kmb_sha256(circ)\n    log(f\'raw build {rep_raw} ({time.time() - t0:.1f}s)\')\n    final = circ\n    exact_stats = None\n    if cfg.get(\'exact_pass\', True):\n        final, exact_stats = Ex.run(circ, work)\n        log(f\'exact pass {exact_stats} ({time.time() - t0:.1f}s)\')\n    rep = Ck.report(final, phase_fn, margin, nbatch=nbatch)\n    rep[\'sha256\'] = kmb_sha256(final)\n    log(f\'final {rep} ({time.time() - t0:.1f}s)\')\n    if out_path:\n        final.to_file(out_path, format=\'kmb\')\n    return {\'cfg\': cfg, \'tag\': tg, \'model\': model, \'windows\': {\'A\': W, \'wcb\': o.wcb}, \'raw\': rep_raw,\n            \'exact_stats\': exact_stats, \'final\': rep, \'seconds\': round(time.time() - t0, 1),\n            \'tables_sha256\': hashlib.sha256(tables.tobytes()).hexdigest(),\n            \'angles\': [[int(v) for v in ang] for ang in angs]}\n\n\ndef main(argv):\n    cfg_path, work, out_path = argv[0], argv[1], argv[2]\n    with open(cfg_path, encoding=\'utf-8\') as f:\n        cfg = json.load(f)\n    res = run(cfg, work, out_path)\n    rep_path = os.path.splitext(out_path)[0] + \'.report.json\'\n    with open(rep_path, \'w\', encoding=\'utf-8\') as f:\n        json.dump(res, f, indent=1)\n    print(json.dumps({k: v for k, v in res.items() if k != \'angles\'}, indent=1))\n\n\nif __name__ == \'__main__\':\n    main(sys.argv[1:])\n', 'invsqrt/model.py': '"""Exact integer model of the invsqrt circuit (single-bit normalization, centred quadratic).\n\nPorted from marsyas\'s Apache-2.0 notebook (see package docstring). change: only the\nsigned-digit ("sd") row mode the 13.94x build uses is kept; the Booth and plain-row\nmodes are dropped. The reference cache path is a parameter.\n\nNotation\n  x in [1, MAX_X], 22-bit. t = 21 - floor(log2 x) (leading zeros), x_n = x << t in [2^21, 2^22).\n  t = 16 f16 + 8 f8 + 4 f4 + 2 f2 + f1,  s = t >> 1,  p = f1.\n  1/sqrt(x) = 2^(s-10) * Y,  Y = (p ? 1 : 2^-1/2) / sqrt(x_n / 2^21)  in (1/2, 1].\n  Segment address a = (p << 7) | ((x_n >> 14) & 127); delta_int b = x_n & 0x3FFF (14 bits).\n  Signed digits: d\' = sum_i (2 b_i - 1) 2^(i-22), rows rounded.\n\nArithmetic (all integer):\n  T  = C1 - sum_{i in rowsA} (2b_i - 1) rd(C2, eA_i + 1)        (step A)\n  Y\' = C0 - sum_{i in rowsB} (2b_i - 1) rd(T,  eB_i + 1)  mod 2^(F0-1)   (step B)\n  eA_i = 21 + F2 - FT - i, eB_i = 21 + FT - F0 - i.\n  Phase (turns) = 2^(s-10) * (Y\' 2^-F0 + 1/2).\n"""\nfrom __future__ import annotations\n\nimport math\nimport os\nfrom dataclasses import dataclass\n\nimport numpy as np\n\nMAX_X = 3133452\nWIDTH = 22\nMASK64 = (1 << 64) - 1\n\n\ndef shr(v, e):\n    """v * 2^-e floored (e may be negative)."""\n    return (v >> e) if e >= 0 else (v << -e)\n\n\n@dataclass(frozen=True)\nclass Params:\n    F0: int = 28          # Y LSB weight 2^-F0; register holds Y - 1/2 in F0-1 bits\n    FT: int = 19          # T LSB 2^-FT\n    F2: int = 8           # C2 LSB 2^-F2; register F2-1 bits\n    G0: int = 1           # unrotated guard LSBs of Y\' (phase uses Y\' >> G0)\n    rowsA: tuple = tuple(range(14))\n    rowsB: tuple = tuple(range(14))\n    tcap: bool = True     # T < 2^(FT-1): T register FT-1 bits\n\n    @property\n    def nT(self):\n        return self.FT - 1 if self.tcap else self.FT\n\n    def eA(self, i):\n        return 21 + self.F2 - self.FT - i\n\n    def eB(self, i):\n        return 21 + self.FT - self.F0 - i\n\n\ndef decompose(xs):\n    xs = np.asarray(xs, dtype=np.int64)\n    lg = np.floor(np.log2(xs.astype(np.float64))).astype(np.int64)\n    lg = np.where((1 << (lg + 1)) <= xs, lg + 1, lg)\n    lg = np.where((1 << lg) > xs, lg - 1, lg)\n    t = 21 - lg\n    xn = xs << t\n    p = t & 1\n    s = t >> 1\n    return t, xn, p, s\n\n\ndef reference(cache_path=None):\n    """Verifier target (uint64 units of 2^-64 turns) and tolerance for every x, as in\n    verify_submission_invsqrt.reference_values with beta = 1, precision_bits = 24."""\n    if cache_path and os.path.exists(cache_path):\n        with np.load(cache_path) as z:\n            return z[\'target\'], z[\'tol\']\n    rs = [math.isqrt((1 << 130) // x) for x in range(1, MAX_X + 1)]\n    target = np.array([((r + 1) >> 1) & MASK64 for r in rs], dtype=np.uint64)\n    tol = np.array([min(r >> 25, 1 << 63) for r in rs], dtype=np.uint64)\n    if cache_path:\n        os.makedirs(os.path.dirname(cache_path), exist_ok=True)\n        np.savez(cache_path, target=target, tol=tol)\n    return target, tol\n\n\ndef rd(v, s):\n    """v * 2^-s rounded half up (s <= 0: exact left shift)."""\n    if s <= 0:\n        return v << (-s)\n    return (v >> s) + ((v >> (s - 1)) & 1)\n\n\ndef sd_apply(acc, op, b, rows, e_of):\n    for i in rows:\n        sig = 2 * ((b >> i) & 1) - 1\n        acc = acc - sig * rd(op, e_of(i) + 1)\n    return acc\n\n\ndef eval_T(C1, C2, b, prm: Params):\n    return sd_apply(C1.copy(), C2, b, prm.rowsA, prm.eA)\n\n\ndef eval_Y(C0, T, b, prm: Params):\n    return sd_apply(C0.copy(), T, b, prm.rowsB, prm.eB)\n\n\ndef rotation_cost(n_rot, min_margin_units):\n    """T count of n_rot rotations at the verifier\'s eps for a given minimum margin."""\n    eps = math.pi * min_margin_units / 2**64 / n_rot\n    return n_rot * (0.56 * math.log2(1 / eps) + 5.3)\n\n\ndef window_ranges1(tables, prm: Params, xn, p):\n    """1-guard offset scheme: minimal W with (acc mod 2^(W+1)) - 2^W + d in [-2^(W+1), 2^(W+1))."""\n    a = (p << 7) | ((xn >> 14) & 127)\n    b = xn & 0x3FFF\n    C0, C1, C2 = tables[a, 0], tables[a, 1], tables[a, 2]\n    T = eval_T(C1, C2, b, prm)\n    Y = eval_Y(C0, T, b, prm)\n    out = {}\n    for name, acc, d, n in ((\'A\', C1, T - C1, prm.nT), (\'B\', C0, Y - C0, prm.F0 - 1)):\n        W = None\n        for w in range(1, n - 1):\n            r = (acc & ((1 << (w + 1)) - 1)) - (1 << w) + d\n            if r.min() >= -(1 << (w + 1)) and r.max() < (1 << (w + 1)):\n                W = w\n                break\n        out[name] = W\n    return out\n'}
CONFIG = {'_note': 'marsyas 13.94x arguments: 28 19 8 1 sd=1 dropA=5 LB=21 S=20 mdel=1 wins=17:11,10;15:9,8;13:7,6;11:5,4;9:3,2;7:1,0 (drop defaults to 1, g1 to 1, tcap to 1, fit radii (6,3))', 'F0': 28, 'FT': 19, 'F2': 8, 'G0': 1, 'dropA': [5], 'dropB': [], 'LB': 21, 'S': 20, 'drop': 1, 'wins': '17:11,10;15:9,8;13:7,6;11:5,4;9:3,2;7:1,0', 'exact_pass': True}
KMB_B64 = ''
EXPECTED_SHA = 'ff629b0925ebfce1e7da166f895b1105332e7edebe26f359deb32f7c942b5917'
SALT = 'exp-009-S-002'


def log(msg):
    line = f'[{time.strftime("%H:%M:%S")}] {msg}'
    print(line, flush=True)
    with open(OUT / 'kernel.log', 'a') as f:
        f.write(line + '\n')


def find_data_root() -> Path:
    marker = Path('verifiers') / 'invsqrt' / 'verify_submission_invsqrt.py'
    for dirpath, dirnames, _ in os.walk('/kaggle/input'):
        if (Path(dirpath) / marker).is_file():
            return Path(dirpath)
        if dirpath.count(os.sep) > 6:
            dirnames[:] = []
    raise FileNotFoundError('competition data not found under /kaggle/input')


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 22), b''):
            h.update(chunk)
    return h.hexdigest()


def canonical_sha(path: Path) -> str:
    import kickmix as km
    buf = io.BytesIO()
    km.Circuit.from_file(str(path), format='kmb').to_file(buf, format='kmb')
    return hashlib.sha256(buf.getvalue()).hexdigest()


def run_monitored(cmd, cwd, stdout_path):
    """Run cmd, sample summed tree RSS and system used memory every 0.5 s."""
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1')
    t0 = time.time()
    with open(stdout_path, 'w') as fo, open(str(stdout_path) + '.stderr', 'w') as fe:
        p = subprocess.Popen(cmd, cwd=cwd, stdout=fo, stderr=fe, env=env)
        ps = psutil.Process(p.pid)
        peak = {'tree_rss': 0, 'sys_used': 0}
        stop = threading.Event()

        def poll():
            while not stop.is_set():
                try:
                    procs = [ps] + ps.children(recursive=True)
                    rss = sum(q.memory_info().rss for q in procs)
                    peak['tree_rss'] = max(peak['tree_rss'], rss)
                except psutil.Error:
                    pass
                peak['sys_used'] = max(peak['sys_used'], psutil.virtual_memory().used)
                stop.wait(0.5)

        th = threading.Thread(target=poll, daemon=True)
        th.start()
        rc = p.wait()
        stop.set()
        th.join()
    return rc, time.time() - t0, peak


def main():
    info = {'platform': platform.platform(), 'python': sys.version, 'cpu_count': os.cpu_count(),
            'total_mem_bytes': psutil.virtual_memory().total}
    import importlib.metadata as md
    for pkg in ('kickmix', 'numpy', 'scipy'):
        info[pkg] = md.version(pkg)
    log(json.dumps(info))

    # 2. the exact file that goes into the zip
    kmb = OUT / 'invsqrt.kmb'
    kmb.write_bytes(base64.b64decode(KMB_B64))
    emb_file_sha, emb_canon_sha = sha256_file(kmb), canonical_sha(kmb)
    log(f'embedded kmb sha256 file {emb_file_sha} canonical {emb_canon_sha} expected {EXPECTED_SHA}')
    if emb_file_sha != EXPECTED_SHA or emb_canon_sha != EXPECTED_SHA:
        (OUT / 'SHA_MISMATCH_EMBEDDED').write_text(emb_file_sha + ' ' + emb_canon_sha)
        raise SystemExit('embedded circuit hash differs; not verifying')

    # 3. independent rebuild from the committed generator
    src = Path('/kaggle/working/src')
    for rel, text in SOURCES.items():
        p = src / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text, encoding='utf-8')
    (OUT / 'config.json').write_text(json.dumps(CONFIG, indent=1))
    runner = OUT / 'build_runner.py'
    runner.write_text(
        'import sys\n'
        "sys.path.insert(0, '/kaggle/working/src')\n"
        "if __name__ == '__main__':\n"
        '    from invsqrt import generate\n'
        '    generate.main(sys.argv[1:])\n')
    rebuilt = OUT / 'rebuilt.kmb'
    t0 = time.time()
    r = subprocess.run([sys.executable, '-I', '-B', str(runner), str(OUT / 'config.json'), str(OUT / 'work'),
                        str(rebuilt)], capture_output=True, text=True)
    (OUT / 'build.stdout').write_text(r.stdout)
    (OUT / 'build.stderr').write_text(r.stderr)
    build_s = time.time() - t0
    log(f'build rc {r.returncode} in {build_s:.1f}s')
    if r.returncode != 0:
        raise SystemExit('build failed')
    rb_file_sha = sha256_file(rebuilt)
    rebuild_identical = rebuilt.read_bytes() == kmb.read_bytes()
    log(f'rebuilt kmb sha256 {rb_file_sha} byte_identical_to_embedded {rebuild_identical}')
    if not rebuild_identical:
        (OUT / 'REBUILD_MISMATCH').write_text(rb_file_sha)
        raise SystemExit('rebuild differs from the embedded file; not verifying')

    # 4. the official verifier, fresh salt, on the embedded file
    root = find_data_root()
    ver = root / 'verifiers'
    vfile = ver / 'invsqrt' / 'verify_submission_invsqrt.py'
    log(f'verifier {vfile} sha256 {sha256_file(vfile)}')
    cmd = [sys.executable, '-I', '-B', 'invsqrt/verify_submission_invsqrt.py', str(kmb), '--salt', SALT]
    log('running: ' + ' '.join(cmd) + f' (cwd {ver})')
    rc, wall, peak = run_monitored(cmd, ver, OUT / 'verify_full.json')
    summary = {'rc': rc, 'wall_s': wall, 'peak': peak, 'cmd': cmd, 'cwd': str(ver), 'salt': SALT,
               'verified_file_sha256': sha256_file(kmb), 'verified_canonical_sha256': emb_canon_sha,
               'rebuilt_sha256': rb_file_sha, 'rebuild_byte_identical': rebuild_identical, 'build_s': build_s,
               'verifier_sha256': sha256_file(vfile), 'machine': info}
    (OUT / 'verify_meta.json').write_text(json.dumps(summary, indent=1))
    log(json.dumps(summary))
    log((OUT / 'verify_full.json').read_text())


if __name__ == '__main__':
    main()
